<div class="monster-block" @click="closeMonsterList()"><div class="monster-list-block"><div class="monster-list" @click.stop="()=&gt;{}"><div class="monster-list-item" v-for="monsterUse in playerMes.monsterFightList" @click="selectMonsterUse = monsterUse"><div class="monster-list-item-name">{{playerMes.monsterList[monsterUse].name}}</div><div class="monster-list-item-level">{{playerMes.monsterList[monsterUse].level}}</div><div class="monster-select-icon-top" v-if="monsterUse == selectMonsterUse">⬇</div><div class="monster-select-icon-bottom" v-if="monsterUse == selectMonsterUse">⬆</div></div></div><div class="monster-botton-use" @click.stop="fightListOut()">退出出战队列</div></div><div class="monster-list-block"><div class="monster-list" @click.stop="()=&gt;{}"><div class="monster-list-item" :class="playerMes.monsterFightList.includes(index) ? 'monster-list-item-active' : ''" v-for="(monster,index) in playerMes.monsterList" @click="selectMonster = index"><div class="monster-list-item-name">{{monster.name}}</div><div class="monster-list-item-level">{{monster.level}}</div><div class="monster-select-icon-top" v-if="index == selectMonster">⬇</div><div class="monster-select-icon-bottom" v-if="index == selectMonster">⬆</div></div></div><div class="monster-botton" @click.stop="fightListIn()">加入出战队列</div></div><div class="monster-botton-confirm" @click.stop="confirmFight()">保存</div></div>